package com.autojobapply.application;
import com.autojobapply.config.Config; import com.autojobapply.config.ExecutionMode; import com.autojobapply.model.*; import com.autojobapply.tracking.ApplicationTracker;
/** Guard rail: public job feeds do not authorize form submission. An employer-authorized API adapter is required. */
public final class SubmissionService { private final Config config;private final ApplicantProfile profile;private final ApplicationTracker tracker;public SubmissionService(Config c,ApplicantProfile p,ApplicationTracker t){config=c;profile=p;tracker=t;}
 public ApplicationStatus process(ScoredJob job){ExecutionMode mode=config.executionMode();if(mode==ExecutionMode.DISCOVER_ONLY)return ApplicationStatus.MATCHED;ApplicationAttempt attempt=new GreenhouseApplicationAdapter().applyDetailed(job,profile,config.resumePath(),mode,config.autoSubmit(),config.authorizedSubmission());String reason=attempt.status()==ApplicationStatus.SUBMITTED?"Employer confirmation detected":attempt.confirmation();tracker.recordValidation(job,attempt.validation(),attempt.submitAttempted(),attempt.confirmation());tracker.record(job,attempt.status(),reason);return attempt.status();}}
